// React Native for page.native.tsx screens (RFC 0004, 7.2). Generated by @farm.js/mobile/ios only
// for apps with React Native screens. New architecture only: Hermes bytecode, Fabric and
// bridgeless TurboModules, from React Native's prebuilt XCFrameworks. One runtime is shared by
// every native screen, each its own surface.
#import "FarmReactNative.h"

#import <React/RCTAssert.h>
#import <React/RCTBridge+Private.h>
#import <React/RCTBridge.h>
#import <React/RCTBridgeModule.h>
#import <React/RCTBundleManager.h>
#import <React/RCTDevMenu.h>
#import <React/RCTLog.h>
#import <React/RCTSurfaceHostingProxyRootView.h>
#import <React_RCTAppDelegate/RCTDefaultReactNativeFactoryDelegate.h>
#import <React_RCTAppDelegate/RCTDependencyProvider.h>
#import <React_RCTAppDelegate/RCTReactNativeFactory.h>
#import <ReactCommon/RCTHost.h>
#import <os/log.h>
#if FARM_LINKED_MODULES
// Codegen's provider for the linked packages and the app's own modules (FarmModules/).
#import <ReactAppDependencyProvider/RCTAppDependencyProvider.h>
#endif

static os_log_t FarmLog(void)
{
  static os_log_t log;
  static dispatch_once_t once;
  dispatch_once(&once, ^{
    log = os_log_create("dev.farmjs.mobile.shell", "FarmShell");
  });
  return log;
}

/// Open screens by id, so the FarmShell module can reach their navigator host. Main thread only.
static NSMutableDictionary<NSNumber *, id<FarmReactNativeScreenHost>> *FarmScreens(void)
{
  static NSMutableDictionary *screens;
  static dispatch_once_t once;
  dispatch_once(&once, ^{
    screens = [NSMutableDictionary new];
  });
  return screens;
}

static __weak id<FarmReactNativeSession> FarmSession;

static void FarmOnMain(dispatch_block_t block)
{
  if ([NSThread isMainThread]) {
    block();
  } else {
    dispatch_async(dispatch_get_main_queue(), block);
  }
}

#pragma mark - FarmShell

/// `NativeModules.FarmShell` in JS: what @farm.js/native calls to reach the navigator. A module of
/// the TurboModule interop layer, as on Android.
@interface FarmShellModule : NSObject <RCTBridgeModule>
@end

@implementation FarmShellModule

RCT_EXPORT_MODULE(FarmShell)

+ (BOOL)requiresMainQueueSetup
{
  return NO;
}

static void FarmWithScreen(double screen, void (^block)(id<FarmReactNativeScreenHost> host))
{
  FarmOnMain(^{
    id<FarmReactNativeScreenHost> host = FarmScreens()[@((NSInteger)screen)];
    if (host) {
      block(host);
    }
  });
}

RCT_EXPORT_METHOD(visit : (double)screen url : (NSString *)url replace : (BOOL)replace)
{
  FarmWithScreen(screen, ^(id<FarmReactNativeScreenHost> host) {
    [host farmVisit:url replace:replace];
  });
}

RCT_EXPORT_METHOD(fallback : (double)screen reason : (NSString *)reason)
{
  FarmWithScreen(screen, ^(id<FarmReactNativeScreenHost> host) {
    [host farmFallback:reason];
  });
}

RCT_EXPORT_METHOD(setTitle : (double)screen title : (NSString *)title)
{
  FarmWithScreen(screen, ^(id<FarmReactNativeScreenHost> host) {
    [host farmSetTitle:title];
  });
}

RCT_EXPORT_METHOD(rendered : (double)screen)
{
  FarmWithScreen(screen, ^(id<FarmReactNativeScreenHost> host) {
    [host farmRendered];
  });
}

/// `{ appId, accessToken }` for serverFetch; the refresh token never reaches JS.
RCT_EXPORT_METHOD(session : (RCTPromiseResolveBlock)resolve reject : (RCTPromiseRejectBlock)reject)
{
  FarmOnMain(^{
    id<FarmReactNativeSession> session = FarmSession;
    if (!session) {
      resolve(nil);
      return;
    }
    [session farmSession:^(NSString *appId, NSString *accessToken) {
      if (!appId) {
        resolve(nil);
        return;
      }
      resolve(@{@"appId" : appId, @"accessToken" : accessToken ?: (id)[NSNull null]});
    }];
  });
}

RCT_EXPORT_METHOD(
    refreshSession : (NSString *)failedToken resolve : (RCTPromiseResolveBlock)resolve reject : (RCTPromiseRejectBlock)
        reject)
{
  FarmOnMain(^{
    id<FarmReactNativeSession> session = FarmSession;
    if (!session) {
      resolve(nil);
      return;
    }
    [session farmRefreshSession:failedToken
                          reply:^(NSString *token) {
                            resolve(token);
                          }];
  });
}

RCT_EXPORT_METHOD(signOut : (RCTPromiseResolveBlock)resolve reject : (RCTPromiseRejectBlock)reject)
{
  FarmOnMain(^{
    id<FarmReactNativeSession> session = FarmSession;
    if (!session) {
      resolve(nil);
      return;
    }
    [session farmSignOut:^{
      resolve(nil);
    }];
  });
}

/// signIn/signUp from @farm.js/auth/client on a native screen. Resolves `{ status, body }` once the
/// device token is stored; cookies and tokens never reach JS.
RCT_EXPORT_METHOD(
    signIn : (NSString *)path body : (NSString *)body resolve : (RCTPromiseResolveBlock)
        resolve reject : (RCTPromiseRejectBlock)reject)
{
  FarmOnMain(^{
    id<FarmReactNativeSession> session = FarmSession;
    if (!session) {
      reject(@"farm_sign_in", @"The device session is not ready.", nil);
      return;
    }
    [session farmSignIn:path
                   body:body
                  reply:^(NSInteger status, NSString *replyBody, NSString *error) {
                    if (error) {
                      reject(@"farm_sign_in", error, nil);
                    } else {
                      resolve(@{@"status" : @(status), @"body" : replyBody ?: @""});
                    }
                  }];
  });
}

@end

#pragma mark - Dependencies

/// The app's dependency provider: Codegen's RCTAppDependencyProvider when the app links native
/// modules, else empty, which is what Codegen answers for an app that links none. Modules
/// "requiring main queue setup" are set up eagerly by name, so only names that resolve to a
/// class are passed on: Codegen lists React Native's own SampleTurboModule, which the prebuilt
/// framework does not contain (a CocoaPods source build compiles it), and a debug build shows a
/// RedBox for the failed lookup.
@interface FarmDependencyProvider : NSObject <RCTDependencyProvider>
- (instancetype)initWithProvider:(nullable id<RCTDependencyProvider>)provider
                         resolve:(Class _Nullable (^)(NSString *name))resolve;
@end

@implementation FarmDependencyProvider {
  id<RCTDependencyProvider> _provider;
  Class _Nullable (^_resolve)(NSString *);
}

- (instancetype)initWithProvider:(id<RCTDependencyProvider>)provider resolve:(Class (^)(NSString *))resolve
{
  if (self = [super init]) {
    _provider = provider;
    _resolve = [resolve copy];
  }
  return self;
}

- (NSArray<NSString *> *)imageURLLoaderClassNames
{
  return _provider ? _provider.imageURLLoaderClassNames : @[];
}

- (NSArray<NSString *> *)imageDataDecoderClassNames
{
  return _provider ? _provider.imageDataDecoderClassNames : @[];
}

- (NSArray<NSString *> *)URLRequestHandlerClassNames
{
  return _provider ? _provider.URLRequestHandlerClassNames : @[];
}

- (NSArray<NSString *> *)unstableModulesRequiringMainQueueSetup
{
  NSMutableArray<NSString *> *modules = [NSMutableArray new];
  for (NSString *name in _provider ? _provider.unstableModulesRequiringMainQueueSetup : @[]) {
    if (_resolve(name)) {
      [modules addObject:name];
    }
  }
  return modules;
}

- (NSDictionary<NSString *, Class<RCTComponentViewProtocol>> *)thirdPartyFabricComponents
{
  return _provider ? _provider.thirdPartyFabricComponents : @{};
}

- (NSDictionary<NSString *, id<RCTModuleProvider>> *)moduleProviders
{
  return _provider ? _provider.moduleProviders : @{};
}

@end

#pragma mark - Factory delegate

@interface FarmReactNativeDelegate : RCTDefaultReactNativeFactoryDelegate
@property (nonatomic, strong) NSURL *farmBundleURL;
@property (nonatomic, copy) void (^farmStarted)(void);
@end

@implementation FarmReactNativeDelegate

- (NSURL *)bundleURL
{
  return self.farmBundleURL;
}

- (NSURL *)sourceURLForBridge:(RCTBridge *)bridge
{
  return self.farmBundleURL;
}

- (Class)getModuleClassFromName:(const char *)name
{
  if (strcmp(name, "FarmShell") == 0) {
    return FarmShellModule.class;
  }
  Class core = [super getModuleClassFromName:name];
  if (core) {
    return core;
  }
  // Modules that register with RCT_EXPORT_MODULE: linked packages such as netinfo, the app's
  // own (DeviceModule.mm), and React Native's own, which the runtime looks up by name when it
  // sets up the ones that ask for the main queue. CocoaPods apps reach them the same way.
  static NSDictionary<NSString *, Class> *registered;
  static dispatch_once_t once;
  dispatch_once(&once, ^{
    NSMutableDictionary<NSString *, Class> *byName = [NSMutableDictionary new];
    for (Class moduleClass in RCTGetModuleClasses()) {
      byName[RCTBridgeModuleNameForClass(moduleClass)] = moduleClass;
    }
    registered = byName;
  });
  return registered[@(name)];
}

- (void)hostDidStart:(RCTHost *)host
{
  if ([RCTDefaultReactNativeFactoryDelegate instancesRespondToSelector:@selector(hostDidStart:)]) {
    [super hostDidStart:host];
  }
  void (^started)(void) = self.farmStarted;
  if (started) {
    FarmOnMain(started);
  }
}

@end

#pragma mark - Engine

@interface FarmReactNative ()
@property (nonatomic, readwrite, nullable) NSString *failure;
@end

@implementation FarmReactNative {
  FarmReactNativeDelegate *_delegate;
  RCTReactNativeFactory *_factory;
  BOOL _dev;
  BOOL _hostCreated;
  NSMutableDictionary<NSNumber *, RCTSurfaceHostingView *> *_views;
}

+ (id<FarmReactNativeSession>)session
{
  return FarmSession;
}

+ (void)setSession:(id<FarmReactNativeSession>)session
{
  FarmSession = session;
}

- (instancetype)initWithBundleURL:(NSURL *)bundleURL dev:(BOOL)dev
{
  if (self = [super init]) {
    _dev = dev;
    _views = [NSMutableDictionary new];
    _delegate = [FarmReactNativeDelegate new];
    _delegate.farmBundleURL = bundleURL;
#if FARM_LINKED_MODULES
    id<RCTDependencyProvider> generated = [RCTAppDependencyProvider new];
#else
    id<RCTDependencyProvider> generated = nil;
#endif
    __weak FarmReactNativeDelegate *weakDelegate = _delegate;
    _delegate.dependencyProvider = [[FarmDependencyProvider alloc] initWithProvider:generated
                                                                            resolve:^Class(NSString *name) {
                                                                              return [weakDelegate
                                                                                  getModuleClassFromName:name.UTF8String];
                                                                            }];
    __weak FarmReactNative *weakSelf = self;
    _delegate.farmStarted = ^{
      void (^started)(void) = weakSelf.onStarted;
      if (started) {
        started();
      }
    };
    if (!dev) {
      // A build reports fatal errors to the navigator instead of crashing: open screens show
      // their web twin, and later opens do too (RFC 0004, decisions: the web twin).
      RCTSetFatalHandler(^(NSError *error) {
        [weakSelf fail:error.localizedDescription ?: @"React Native fatal error"];
      });
      RCTSetFatalExceptionHandler(^(NSException *exception) {
        [weakSelf fail:[NSString stringWithFormat:@"%@: %@", exception.name, exception.reason]];
      });
    }
  }
  return self;
}

/// The factory and its host, created on first use.
- (RCTReactNativeFactory *)factory
{
  if (!_factory) {
    _factory = [[RCTReactNativeFactory alloc] initWithDelegate:_delegate];
  }
  return _factory;
}

- (void)warm
{
  if (self.failure && !_dev) {
    return;
  }
  if (_hostCreated) {
    return;
  }
  _hostCreated = YES;
  CFTimeInterval started = CACurrentMediaTime();
  @try {
    [self.factory.rootViewFactory initializeReactHostWithLaunchOptions:nil
                                                   bundleConfiguration:[RCTBundleConfiguration defaultConfiguration]
                                                  devMenuConfiguration:[RCTDevMenuConfiguration defaultConfiguration]];
  } @catch (NSException *exception) {
    [self fail:[NSString stringWithFormat:@"%@: %@", exception.name, exception.reason]];
    return;
  }
  os_log(
      FarmLog(), "react-native host created in %ldms dev=%d", (long)((CACurrentMediaTime() - started) * 1000), _dev);
}

- (UIView *)openModule:(NSString *)module
                screen:(NSInteger)screen
            properties:(NSDictionary<NSString *, id> *)properties
                  host:(id<FarmReactNativeScreenHost>)host
{
  if (self.failure && !_dev) {
    return nil;
  }
  self.failure = nil;
  [self warm];
  if (self.failure) {
    return nil;
  }
  FarmScreens()[@(screen)] = host;
  @try {
    UIView *view = [self.factory.rootViewFactory viewWithModuleName:module initialProperties:properties];
    if ([view isKindOfClass:RCTSurfaceHostingView.class]) {
      _views[@(screen)] = (RCTSurfaceHostingView *)view;
    }
    return view;
  } @catch (NSException *exception) {
    [FarmScreens() removeObjectForKey:@(screen)];
    [self fail:[NSString stringWithFormat:@"%@: %@", exception.name, exception.reason]];
    return nil;
  }
}

- (void)closeScreen:(NSInteger)screen
{
  [FarmScreens() removeObjectForKey:@(screen)];
  RCTSurfaceHostingView *view = _views[@(screen)];
  [_views removeObjectForKey:@(screen)];
  // The surface unmounts its React tree; the runtime stays for the next native screen.
  [view.surface stop];
}

- (void)fail:(NSString *)reason
{
  os_log_error(FarmLog(), "react-native failed, native screens fall back to web: %{public}@", reason);
  FarmOnMain(^{
    self.failure = reason;
    NSArray<id<FarmReactNativeScreenHost>> *open = FarmScreens().allValues;
    [FarmScreens() removeAllObjects];
    for (id<FarmReactNativeScreenHost> host in open) {
      [host farmFallback:reason];
    }
    void (^failed)(NSString *) = self.onFailure;
    if (failed) {
      failed(reason);
    }
  });
}

@end
